// Package db opens Ash Cloud's SQLite database and keeps its schema current.
//
// Queries live in queries/*.sql and the schema in migrations/*.sql; the Go
// code for the queries (db.go, models.go, *.sql.go) is generated by sqlc.
package db

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"net/url"

	"github.com/pressly/goose/v3"
	"modernc.org/sqlite"
	sqlite3 "modernc.org/sqlite/lib"
)

//go:embed migrations/*.sql
var migrationFiles embed.FS

// Open opens the SQLite database at path, creating the file if needed.
func Open(ctx context.Context, path string) (*sql.DB, error) {
	options := url.Values{
		"_pragma": {
			"journal_mode(WAL)",   // readers never block the writer
			"synchronous(NORMAL)", // safe with WAL, and much faster than FULL
			"busy_timeout(5000)",  // wait up to 5 s for a lock instead of failing
			"foreign_keys(1)",
		},
		// Take the write lock when a transaction starts, so two transactions
		// can't both read and then deadlock trying to upgrade to writing.
		"_txlock": {"immediate"},
	}
	database, err := sql.Open("sqlite", path+"?"+options.Encode())
	if err != nil {
		return nil, err
	}
	if err := database.PingContext(ctx); err != nil {
		database.Close()
		return nil, fmt.Errorf("open database %s: %w", path, err)
	}
	return database, nil
}

// Migrate applies the schema changes the database doesn't have yet and
// returns the versions it applied (empty when already up to date).
func Migrate(ctx context.Context, database *sql.DB) ([]int64, error) {
	provider, err := newMigrator(database)
	if err != nil {
		return nil, err
	}
	results, err := provider.Up(ctx)
	applied := make([]int64, 0, len(results))
	for _, result := range results {
		if result.Error == nil {
			applied = append(applied, result.Source.Version)
		}
	}
	if err != nil {
		return applied, fmt.Errorf("update database schema: %w", err)
	}
	return applied, nil
}

func newMigrator(database *sql.DB) (*goose.Provider, error) {
	files, err := fs.Sub(migrationFiles, "migrations")
	if err != nil {
		return nil, err
	}
	return goose.NewProvider(goose.DialectSQLite3, database, files, goose.WithDisableGlobalRegistry(true))
}

// Check proves the database file can be read. Used by /readyz.
func Check(ctx context.Context, database *sql.DB) error {
	var tables int
	return database.QueryRowContext(ctx, "SELECT count(*) FROM sqlite_schema").Scan(&tables)
}

// IsUniqueViolation reports whether err is a UNIQUE constraint failure,
// for example creating a user whose name is taken.
func IsUniqueViolation(err error) bool {
	var sqliteErr *sqlite.Error
	return errors.As(err, &sqliteErr) && sqliteErr.Code() == sqlite3.SQLITE_CONSTRAINT_UNIQUE
}
